import React, { useRef } from 'react';
import { Messages } from 'primereact/messages';
import { useMountEffect } from 'primereact/hooks';

export default function Basic() {
    const msgs = useRef(null);

    useMountEffect(() => {
        if (msgs.current) {
            msgs.current.clear();
            msgs.current.show({ id: '1', sticky: true, severity: 'info', summary: 'Info', detail: 'Message Content sdasd', closable: false });
        }
    }); 

    return (
        <Messages ref={msgs} />
    )
}